mapper.update:
update sys_staff
staff_no = #{staffNo}, name = #{name}, username = #{username}, password = #{password}, phone = #{phone}, avatar = #{avatar}, role = #{role}, skill_tags = #{skillTags}, workload_limit = #{workloadLimit}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select s.id, s.staff_no, s.name, s.username, s.phone, s.role, s.skill_tags, s.workload_limit, s.status, (select count(*) from wo_order o where o.assignee_id = s.id and o.status in (3,4,5,6,8)) as active_count from sys_staff s
and s.name like concat('%', #{name}, '%') and s.role = #{role} and s.status = #{status}
order by s.role, s.staff_no
